static NSString *Note(int n){static NSArray *names=@[@"A",@"A♯",@"B",@"C",@"C♯",@"D",@"D♯",@"E",@"F",@"F♯",@"G",@"G♯"];return [NSString stringWithFormat:@"%@%d",names[n%12],(n+9)/12];}
static int ParseNote(NSString *s){NSString *t=[s stringByReplacingOccurrencesOfString:@"♯" withString:@"#"];for(int n=0;n<88;n++)if([[Note(n) stringByReplacingOccurrencesOfString:@"♯" withString:@"#"] isEqualToString:t])return n;return -1;}
static UILabel *Label(NSString *text,CGFloat size){UILabel *l=[UILabel new];l.text=text;l.font=[UIFont monospacedDigitSystemFontOfSize:size weight:UIFontWeightMedium];l.textAlignment=NSTextAlignmentCenter;l.numberOfLines=0;return l;}
@interface TLGraph:UIView
@property(nonatomic,strong) NSArray *values;
@property(nonatomic) BOOL spectrum;
@property(nonatomic) CGFloat cents,phase;
@end
@implementation TLGraph
- (void)drawRect:(CGRect)rect {
    CGContextRef c=UIGraphicsGetCurrentContext();CGRect box=CGRectInset(self.bounds,12,12);[[UIColor secondarySystemBackgroundColor] setFill];UIRectFill(self.bounds);
    if(self.values.count){CGFloat lo=self.spectrum?0:CGFLOAT_MAX,hi=self.spectrum?1:-CGFLOAT_MAX;for(NSNumber *v in self.values){lo=MIN(lo,v.doubleValue);hi=MAX(hi,v.doubleValue);}if(hi-lo<1)hi=lo+1;CGContextSetStrokeColorWithColor(c,UIColor.systemTealColor.CGColor);CGContextSetLineWidth(c,2);for(NSUInteger i=0;i<self.values.count;i++){CGFloat x=box.origin.x+box.size.width*i/MAX(1,self.values.count-1),y=CGRectGetMaxY(box)-box.size.height*([self.values[i] doubleValue]-lo)/(hi-lo);if(i==0)CGContextMoveToPoint(c,x,y);else CGContextAddLineToPoint(c,x,y);}CGContextStrokePath(c);return;}
    CGContextSetStrokeColorWithColor(c,UIColor.tertiaryLabelColor.CGColor);CGContextMoveToPoint(c,CGRectGetMidX(box),box.origin.y);CGContextAddLineToPoint(c,CGRectGetMidX(box),CGRectGetMaxY(box));CGContextStrokePath(c);
    CGFloat x=CGRectGetMidX(box)+MAX(-50,MIN(50,self.cents))/100*box.size.width;[fabs(self.cents)<1?UIColor.systemGreenColor:UIColor.systemOrangeColor setFill];UIRectFill(CGRectMake(x-3,box.origin.y,6,box.size.height*.6));
    CGFloat phase=self.phase-floor(self.phase);for(int i=-1;i<9;i++){CGFloat px=box.origin.x+(i+phase)*box.size.width/8;[UIColor.systemTealColor setFill];UIRectFill(CGRectMake(px,CGRectGetMaxY(box)-18,box.size.width/16,14));}
}
@end
