- (UIButton*)button:(NSString*)text action:(SEL)selector {UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];UIButtonConfiguration *config=[UIButtonConfiguration tintedButtonConfiguration];config.title=text;config.cornerStyle=UIButtonConfigurationCornerStyleMedium;b.configuration=config;[b addTarget:self action:selector forControlEvents:UIControlEventTouchUpInside];[b.heightAnchor constraintGreaterThanOrEqualToConstant:44].active=YES;return b;}
