    [stack addArrangedSubview:[self row:@[[self button:@"预测量 / 过拉" action:@selector(overpullMenu)],[self button:@"考试 / 对比" action:@selector(examMenu)]]]];
    [stack addArrangedSubview:Label(@"实时频谱 · 20 Hz — 10 kHz（对数轴）",13)];_spectrum=[TLGraph new];_spectrum.spectrum=YES;[_spectrum.heightAnchor constraintEqualToConstant:130].active=YES;[stack addArrangedSubview:_spectrum];
    [stack addArrangedSubview:Label(@"当前基音拉伸曲线 · A0 — C8",13)];_curveView=[TLGraph new];[_curveView.heightAnchor constraintEqualToConstant:130].active=YES;[stack addArrangedSubview:_curveView];
    __weak TLMain *weak=self;
    _audio.status=^(NSString *text){TLMain *s=weak;if(s){s->_status.text=text;s->_running=[s->_audio isRunning];if(!s->_running)s->_toneEnabled=NO;UIApplication.sharedApplication.idleTimerDisabled=s->_running;}};
